        h.startSequence().thenWaitUntil(()->h.assertTrue(ItemStack.matches(arm.getHeldItem(),named(7)),"Arm owns actual acquired batch")).thenExecuteAfter(25,()->{h.assertValueEqual(count(h,second,named(1)),0L,"Forced output does not skip its full first inventory");h.assertTrue(ItemStack.matches(arm.getHeldItem(),named(7)),"Exact real held batch waits without loss");receiveBatch(h,64);h.assertValueEqual(receiptCount(h),64L,"Original blocking stock remains in a real receipt owner");}).thenWaitUntil(()->{h.assertValueEqual(count(h,OUTPUT,named(1)),7L,"Held original batch reaches first output when it genuinely has room");h.assertValueEqual(receiptCount(h)+count(h,OUTPUT,named(1)),71L,"All original64 blocking and7 transported diamonds remain real");}).thenSucceed();
