    @GameTest(structure=STRUCTURE) public void trueRemovalDropsHeldComponentsOnceAndUnloadDoesNotDropThem(GameTestHelper h){
        var arm=fixture(h,false);hand(arm,named(7));arm.setRemoved();h.assertTrue(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(h.absolutePos(P)).inflate(1)).isEmpty(),"Actual unload lifecycle does not export the claw's owned stock");arm.clearRemoved();h.setBlock(P,Blocks.AIR);
        var items=h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(h.absolutePos(P)).inflate(1));
        h.assertValueEqual(items.stream().filter(item->ItemStack.isSameItemSameComponents(item.getItem(),named(1))).mapToInt(item->item.getItem().getCount()).sum(),7,"True block removal returns exactly original seven named diamonds");h.assertTrue(arm.getHeldItem().isEmpty(),"Removed source no longer owns a second copy");h.succeed();
    }
    @GameTest(structure=STRUCTURE,maxTicks=200) public void physicalBearingCaptureAndReturnPreserveHandAndDisableTheStaleWorldArm(GameTestHelper h){
        var original=fixture(h,false);hand(original,named(7));var bearingPos=P.below();var motor=bearingPos.below();
        h.setBlock(bearingPos,AllBlocks.MECHANICAL_BEARING.defaultBlockState().setValue(com.simibubi.create.content.contraptions.bearing.BearingBlock.FACING,Direction.UP));
        h.setBlock(motor,AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(CreativeMotorBlock.FACING,Direction.UP));h.getBlockEntity(motor,KineticBlockEntity.class).setGeneratedSpeed(0);
        h.setBlock(P.south(3).below(),Blocks.STONE);var session=NativeSurvivalTestPlayer.join(h,Vec3.atBottomCenterOf(h.absolutePos(P.south(3))));
        var bearing=h.getBlockEntity(bearingPos,com.simibubi.create.content.contraptions.bearing.MechanicalBearingBlockEntity.class);
        h.startSequence().thenWaitUntil(()->{
            try{var checked=new HashSet<Long>();for(var pos:List.of(P,bearingPos)){com.simibubi.create.foundation.utility.LoadedEntityAccess.requireReady(h.getLevel(),h.absolutePos(pos));com.simibubi.create.foundation.utility.LoadedEntityAccess.requireGlueQueriesReady(h.getLevel(),h.absolutePos(pos),checked);}}
            catch(com.simibubi.create.content.contraptions.AssemblyException pending){h.assertTrue(false,"Waiting for actual native source and glue query visibility before physical capture");}
        }).thenExecute(()->{h.useBlock(bearingPos,session.player());h.getBlockEntity(motor,KineticBlockEntity.class).setGeneratedSpeed(16);}).thenWaitUntil(()->{
            h.assertTrue(bearing.isRunning()&&bearing.getMovedContraption()!=null&&h.getBlockState(P).isAir(),"Actual powered bearing captures and removes the real source arm");
        }).thenExecute(()->{
            h.assertTrue(original.isRemoved()&&!original.isActiveWorldOwner(),"Former world block entity has genuinely left the world");
            h.assertTrue(original.takeHeldItem().isEmpty(),"Stale old arm cannot export a second seven-item copy");
            h.assertTrue(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(h.absolutePos(P)).inflate(3),item->item.getItem().is(Items.DIAMOND)).isEmpty(),"Native capture flags do not drop world copies of carried arm stock");
            h.useBlock(bearingPos,session.player());
        }).thenWaitUntil(()->{
            h.assertTrue(!bearing.isRunning()&&h.getLevel().getBlockEntity(h.absolutePos(P)) instanceof ArmBlockEntity returned&&returned!=original&&returned.isActiveWorldOwner()&&ItemStack.matches(returned.getHeldItem(),named(7)),"True native disassembly restores one fresh world owner and exactly original held components");
            h.assertTrue(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(h.absolutePos(P)).inflate(3),item->item.getItem().is(Items.DIAMOND)).isEmpty(),"Physical return does not create cargo drops");
        }).thenExecute(session::close).thenSucceed();
    }
    @GameTest(structure=STRUCTURE) public void relativeSourceCodecTransformsRealTargetsAndPreservesExactHeldComponents(GameTestHelper h){var arm=fixture(h,false);hand(arm,named(7));arm.setSelectionMode(ArmBlockEntity.SelectionMode.PREFER_FIRST);arm.setGoggles();var tag=arm.saveWithFullMetadata(h.getLevel().registryAccess());var restored=(ArmBlockEntity)BlockEntity.loadStatic(arm.getBlockPos(),arm.getBlockState(),tag,h.getLevel().registryAccess());h.assertTrue(restored!=null&&ItemStack.matches(restored.getHeldItem(),named(7)),"Native save restores original component-bearing hand");h.assertTrue(restored.hasGoggles()&&restored.getSelectionMode()==ArmBlockEntity.SelectionMode.PREFER_FIRST,"Source accessories and actual policy survive native codec");h.assertTrue(restored.interactionPoints().equals(arm.interactionPoints()),"Original relative Type/Pos/Mode targets survive");restored.transform(restored,new StructureTransform(new BlockPos(11,0,13),0,90,0));h.assertTrue(restored.interactionPoints().getFirst().pos().equals(new BlockPos(-2,0,0)),"Real structure rotation transforms relative north endpoint west without adding world offset");h.assertTrue(restored.interactionPoints().getFirst().mode()==ArmInteractionPoint.Mode.TAKE&&ItemStack.matches(restored.getHeldItem(),named(7)),"Actual transform retains mode and one authoritative hand");var encoded=endpoint(h,INPUT).serialize(h.absolutePos(P));h.assertTrue(encoded.getCompound("Pos").isPresent(),"Source X/Y/Z compound shape is retained");var malformed=encoded.copy();malformed.putString("Mode","INVALID");h.assertTrue(ArmInteractionPoint.deserialize(malformed,h.getLevel(),h.absolutePos(P))==null,"Malformed mode is rejected without an exception");h.succeed();}
    @GameTest(structure=STRUCTURE) public void targetRangeDuplicatesAndDepositOnlyModesAreValidatedAgainstRealWorld(GameTestHelper h){var arm=fixture(h,false);h.assertFalse(arm.configurePoints(List.of(point(h,OUTPUT,"depot",ArmInteractionPoint.Mode.DEPOSIT),point(h,OUTPUT,"depot",ArmInteractionPoint.Mode.TAKE))),"One real block cannot be both duplicated endpoints");h.setBlock(P.east(5),AllBlocks.DEPOT);h.assertFalse(arm.configurePoints(List.of(point(h,P.east(5),"depot",ArmInteractionPoint.Mode.DEPOSIT))),"Original strict five-block boundary is outside range");h.setBlock(OUTPUT,Blocks.RESPAWN_ANCHOR);h.assertFalse(arm.configurePoints(List.of(point(h,OUTPUT,"respawn_anchor",ArmInteractionPoint.Mode.TAKE))),"Deposit-only actual anchor cannot be forged into an input");for(var id:List.of("basin","belt","blaze_burner","chute","crafter","crushing_wheels","deployer","depot","funnel","millstone","packager","saw","campfire","composter","jukebox","respawn_anchor"))h.assertTrue(CreateBuiltInRegistries.ARM_INTERACTION_POINT_TYPE.containsKey(Create.asResource(id)),"Actual source target factory is registered: "+id);h.succeed();}
    @GameTest(structure=STRUCTURE) public void placementPacketRoundTripBoundsAndAbsentNonceCannotRewriteExistingArm(GameTestHelper h){var arm=fixture(h,false);var points=arm.interactionPoints();var buffer=new RegistryFriendlyByteBuf(Unpooled.buffer(),h.getLevel().registryAccess());try{var packet=new ArmPlacementPacket(points,h.absolutePos(P),17);ArmPlacementPacket.STREAM_CODEC.encode(buffer,packet);var decoded=ArmPlacementPacket.STREAM_CODEC.decode(buffer);h.assertTrue(decoded.equals(packet),"Actual native wire preserves ordered relative endpoints and placement token");}finally{buffer.release();}try(var session=NativeSurvivalTestPlayer.join(h,Vec3.atCenterOf(h.absolutePos(P)).add(0,0,2))){h.assertFalse(new ArmPlacementPacket(List.of(),h.absolutePos(P),0).apply(session.player()),"A normal nearby player cannot configure an old arm with no placement token");h.assertTrue(arm.interactionPoints().equals(points),"Rejected packet preserves actual saved targets");session.player().setPos(Vec3.atCenterOf(h.absolutePos(P)).add(0,0,100));h.assertFalse(new ArmNetworking.Settings(h.absolutePos(P),ArmBlockEntity.SelectionMode.PREFER_FIRST).apply(session.player()),"Remote native settings are rejected");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void nativeTargetCodecAndWirePreserveFlatAddonFieldsWithoutMutableAliases(GameTestHelper h){
        fixture(h,false);var extension=new CompoundTag();var nested=new CompoundTag();nested.putString("FilterName","Actual addon endpoint settings");extension.put("AddonSettings",nested);
        var data=new ArmInteractionPoint.PointData(Create.asResource("depot"),INPUT.subtract(P),ArmInteractionPoint.Mode.TAKE,extension);
        nested.putString("FilterName","Mutated caller alias");data.extra().putString("Injected","Mutated getter alias");
        var tag=(CompoundTag)ArmInteractionPoint.PointData.CODEC.encodeStart(NbtOps.INSTANCE,data).getOrThrow();
        h.assertTrue(tag.getCompound("AddonSettings").orElseThrow().getStringOr("FilterName","").equals("Actual addon endpoint settings")&&!tag.contains("Injected"),"Native target snapshot owns original flat addon fields without aliases");
        var decoded=ArmInteractionPoint.PointData.CODEC.parse(NbtOps.INSTANCE,tag).getOrThrow();h.assertTrue(decoded.equals(data),"Native source-compatible flat NBT preserves addon fields beside Type/Pos/Mode");
        var buffer=new RegistryFriendlyByteBuf(Unpooled.buffer(),h.getLevel().registryAccess());try{var packet=new ArmPlacementPacket(List.of(data),h.absolutePos(P),19);ArmPlacementPacket.STREAM_CODEC.encode(buffer,packet);h.assertTrue(ArmPlacementPacket.STREAM_CODEC.decode(buffer).equals(packet),"Bounded native placement wire retains exact addon settings");}finally{buffer.release();}
        var armTag=arm(h).saveWithFullMetadata(h.getLevel().registryAccess());armTag.remove("SelectionMode");armTag.putInt("ScrollValue",2);var legacy=(ArmBlockEntity)BlockEntity.loadStatic(h.absolutePos(P),arm(h).getBlockState(),armTag,h.getLevel().registryAccess());h.assertTrue(legacy!=null&&legacy.getSelectionMode()==ArmBlockEntity.SelectionMode.PREFER_FIRST,"Original source ScrollValue policy ordinal migrates through native ValueInput");h.succeed();
    }
    @GameTest(structure=STRUCTURE,maxTicks=100) public void realSurvivalPlacementConsumesOneArmAndOnlyItsCapturedNonceCanConfigureOnce(GameTestHelper h){
        depot(h,INPUT);depot(h,OUTPUT);h.setBlock(P.below(),Blocks.STONE);
        try(var session=NativeSurvivalTestPlayer.join(h,Vec3.atCenterOf(h.absolutePos(P)).add(0,0,2))){
            var player=session.player();player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllBlocks.MECHANICAL_ARM,2));
            var hit=new BlockHitResult(Vec3.atCenterOf(h.absolutePos(P.below())).add(0,.499,0),Direction.UP,h.absolutePos(P.below()),false);
            h.assertTrue(player.getMainHandItem().useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,hit)).consumesAction(),"Actual native BlockItem places in survival");
            h.assertValueEqual(player.getMainHandItem().getCount(),1,"One real arm item is paid");
            ArmPlacementPacket.ClientBoundRequest request=null;Object message;
            while((message=session.channel().readOutbound())!=null)if(message instanceof ClientboundCustomPayloadPacket custom&&custom.payload() instanceof ArmPlacementPacket.ClientBoundRequest actual)request=actual;
            h.assertTrue(request!=null&&request.nonce()!=0&&request.pos().equals(h.absolutePos(P)),"Actual placement sends its real server-generated token");
            var valid=new ArmPlacementPacket(List.of(point(h,INPUT,"depot",ArmInteractionPoint.Mode.TAKE),point(h,OUTPUT,"depot",ArmInteractionPoint.Mode.DEPOSIT)),request.pos(),request.nonce());
            h.assertTrue(valid.apply(player),"Real captured token configures this exact placed owner");
            h.assertFalse(valid.apply(player),"Committed placement token cannot be replayed");
            h.assertTrue(player.getUUID().equals(arm(h).advancementOwner()),"Original registered literal survival placer owns criteria");
        }h.succeed();
    }
